param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
$source=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/Forces/AICF_AIWorldQuotaService.c'))
$strongChecks=@{
 'AICF_AIQuotaBirth.c'=@('ref AICF_AIQuotaGroupQueue m_Queue;','ref AICF_AIQuotaDispatch m_Ticket;');
 'AICF_AIQuotaCreation.c'=@('ref AICF_AIQuotaReservation m_Reservation;','ref AICF_AIQuotaDispatch m_Ticket;','ref AICF_AIQuotaCreationGuard m_Guard;');
 'AICF_AIQuotaBody.c'=@('ref AICF_AIQuotaCreationGuard m_CreationGuard;');
 'AICF_AIQuotaLedger.c'=@('ref AICF_AIQuotaReservation m_Reservation;');
 'AICF_AIWorldQuotaService.c'=@('protected ref AICF_AIQuotaBirth m_QuarantinedBirth;','protected ref AICF_AIQuotaCreation m_QuarantinedCreation;')
}
$strongCount=0
foreach($file in $strongChecks.Keys){
 $text=[IO.File]::ReadAllText((Join-Path $RepositoryRoot ('AIConflictCore/Scripts/Game/AIConflict/Forces/'+$file)))
 foreach($needle in $strongChecks[$file]){if(!$text.Contains($needle)){throw "Inflight ownership lifetime lost: $file $needle"};$strongCount++}
}
function Extract([string]$name){Get-AICFMethodBody ([pscustomobject]@{Source=$source;Code=(ConvertTo-AICFCodeText $source)}) $name}
$methods=''
foreach($name in @('EndExternalCreation','CancelExternalCreationBeforeFactory','RejectExternalCreation','QuarantineBirth','EndGroupBirth','RejectNonNullBirth','MarkExternalNativeCallStarted')){
 $returnType='void';if($name-in@('EndExternalCreation','CancelExternalCreationBeforeFactory','MarkExternalNativeCallStarted')){$returnType='bool'}
 $args='AICF_AIQuotaBirth birth';if($name-like'*External*'-or$name-eq'MarkExternalNativeCallStarted'){$args='AICF_AIQuotaCreation creation'}
 if($name-eq'MarkExternalNativeCallStarted'){$args+=', bool commitAttempt=false'}
 if($name-in@('RejectExternalCreation','QuarantineBirth','RejectNonNullBirth')){$args+=', string reason'}
 $methods+="public $returnType $name($args)"+(Extract $name)+"`n"
}
$methods+='public AICF_AIQuotaBirth FindCurrentBoundBirth(N actor)'+(Extract 'FindCurrentBoundBirth')+"`n"
$methods+='public bool OwnsCurrentBoundBirth(AICF_AIQuotaBirth birth, N actor)'+(Extract 'OwnsCurrentBoundBirth')+"`n"
$methods+='public bool RetainQuarantinedExternalReturn(AICF_AIQuotaCreation creation,N entity)'+(Extract 'RetainQuarantinedExternalReturn')+"`n"
$methods+='public bool RetainQuarantinedGroupReturn(AICF_AIQuotaBirth birth,N entity)'+(Extract 'RetainQuarantinedGroupReturn')+"`n"
$methods+='public bool IsExternalObservationCurrent(AICF_AIQuotaCreation creation,Guard guard,Reservation reservation,Ticket ticket,Body body,N entity)'+(Extract 'IsExternalObservationCurrent')+"`n"
$methods+='public void ObserveExternalFactoryFull(AICF_AIQuotaCreation creation,N entity)'+(Extract 'ObserveExternalFactory').Replace('bool producedKind;','bool producedKind=false;')+"`n"
$methods=$methods.Replace('AICF_AIQuotaCreationGuard','Guard').Replace('AICF_AIQuotaReservation','Reservation').Replace('AICF_AIQuotaDispatch','Ticket').Replace('AICF_AIQuotaBody','Body')
foreach($name in @('ObserveExternalFactory','ObserveGroupFactory')){
 $body=Extract $name
 $cut=$body.IndexOf('if (!entity)')
 if($cut-lt0){throw "Missing actual native observation prefix $name"}
 $arg='AICF_AIQuotaCreation creation';if($name-eq'ObserveGroupFactory'){$arg='AICF_AIQuotaBirth birth'}
 $methods+="public void $($name)Prefix($arg,N entity)"+$body.Substring(0,$cut)+"}`n"
}
