alCreation(c,"constructor failure");need(s.m_bQuarantined&&!c.m_bFinished&&s.m_bNativeBirthBusy&&s.m_CurrentCreation==c,"constructor reject retains exact native-return scope");var returned=new N();errors=AICF_Stage1Diagnostics.Errors;s.ObserveExternalFactoryPrefix(c,returned);need(c.m_bFinished&&c.m_Body!=null&&c.m_Body.Entity==returned&&c.m_Body.m_bQuarantined&&c.m_Status==AICF_EAIQuotaBirthStatus.QUARANTINED&&s.m_QuarantinedCreation==c&&s.m_Ledger.Refunded==0&&!s.m_bNativeBirthBusy&&AICF_Stage1Diagnostics.Errors==errors,"quarantined nonnull return retains exact body and prior failure without refund or admission");need(!s.RetainQuarantinedExternalReturn(c,returned),"late returned body cannot replay finished scope");s=new Service();c=new AICF_AIQuotaCreation{m_Service=s,m_bNativeCallStarted=true,m_Status=AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY,m_Ticket=new Ticket()};s.m_CurrentCreation=c;s.RejectExternalCreation(c,"ctor null");c.m_Ticket.m_bClosed=false;s.ObserveExternalFactoryPrefix(c,null);need(s.m_Ledger.Refunded==1&&s.m_bQuarantined&&c.m_Status==AICF_EAIQuotaBirthStatus.QUARANTINED,"native null refunds once but never clears earlier failure");s=new Service();b=new AICF_AIQuotaBirth{m_Service=s,m_Status=AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY};s.m_CurrentBirth=b;s.RejectNonNullBirth(b,"group ctor");s.ObserveGroupFactoryPrefix(b,returned);need(b.m_bFinished&&b.m_Body.Entity==returned&&b.m_Body.m_bQuarantined&&s.m_QuarantinedBirth==b&&s.m_bQuarantined&&!s.m_bNativeBirthBusy,"group quarantined return retains exact native birth");s=new Service();c=new AICF_AIQuotaCreation{m_Service=s,m_Status=AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY};s.m_CurrentCreation=c;var changedWorld=s;c.OnProducer=()=>changedWorld.WorldCurrent=false;need(!s.MarkExternalNativeCallStarted(c)&&!c.m_bNativeCallStarted,"world swapped by producer guard prevents native call");s=new Service();c=new AICF_AIQuotaCreation{m_Service=s,m_Status=AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY};s.m_CurrentCreation=c;need(s.MarkExternalNativeCallStarted(c,true)&&c.m_Guard.Attempts==1&&c.m_Guard.Calls==1,"owned attempt commits exactly at native marker");need(!s.MarkExternalNativeCallStarted(c,true)&&c.m_Guard.Attempts==1,"duplicate marker cannot spend second attempt");s=new Service();c=new AICF_AIQuotaCreation{m_Service=s,m_Status=AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY};s.m_CurrentCreation=c;c.m_Guard.Allow=false;need(!s.MarkExternalNativeCallStarted(c,true)&&!c.m_bNativeCallStarted&&c.m_Guard.Attempts==0,"pure attempt veto leaves factory unmarked");c.m_Guard.Allow=true;c.ProducerCurrent=false;need(!s.MarkExternalNativeCallStarted(c,true)&&c.m_Guard.Calls==1&&c.m_Guard.Attempts==0,"identity veto before pure attempt commit");s=new Service();c=new AICF_AIQuotaCreation{m_Service=s,m_bNativeCallStarted=true,m_Status=AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY,m_Ticket=new Ticket(),m_Prefab="one"};s.m_CurrentCreation=c;s.ObserveExternalFactoryFull(c,new N());need(c.m_Status==AICF_EAIQuotaBirthStatus.BOUND&&s.m_Ledger.Bound==1&&s.m_aBodies.Count()==1,"full observe positive binds once");s=new Service();c=new AICF_AIQuotaCreation{m_Service=s,m_bNativeCallStarted=true,m_Status=AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY,m_Ticket=new Ticket(),m_Prefab="one"};s.m_CurrentCreation=c;var rejectedService=s;var rejectedCreation=c;c.OnProducer=()=>rejectedService.RejectExternalCreation(rejectedCreation,"producer virtual");s.ObserveExternalFactoryFull(c,new N());need(c.m_Status==AICF_EAIQuotaBirthStatus.QUARANTINED&&c.m_bFinished&&s.m_Ledger.Bound==0&&s.m_aBodies.Count()==0&&s.m_bQuarantined,"full observe producer rejection cannot be overwritten by BOUND");s=new Service();c=new AICF_AIQuotaCreation{m_Service=s,m_bNativeCallStarted=true,m_Status=AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY,m_Ticket=new Ticket(),m_Prefab="one"};s.m_CurrentCreation=c;var kindService=s;var kindCreation=c;c.m_Guard.OnKind=()=>kindService.RejectExternalCreation(kindCreation,"kind virtual");s.ObserveExternalFac