$unsafe=0
foreach($mutation in @(
 @('external-unobserved-close','if (creation.m_Status == AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY) return false;',''),
 @('external-stale-reject','creation != m_CurrentCreation || creation.m_Service != this || creation.m_bFinished || !m_bNativeBirthBusy','creation.m_Service != this'),
 @('group-stale-quarantine','birth != m_CurrentBirth || birth.m_Service != this || birth.m_bFinished || !m_bNativeBirthBusy','birth.m_Service != this'),
 @('group-unobserved-close','if (birth.m_Status == AICF_EAIQuotaBirthStatus.IN_NATIVE_FACTORY) return;',''),
 @('cancel-fake-null','creation.m_Status = AICF_EAIQuotaBirthStatus.VETO;','creation.m_Status = AICF_EAIQuotaBirthStatus.NATIVE_NULL;'),
 @('refund-during-native-constructor','creation.m_bNativeCallStarted || creation.m_bFinished','creation.m_bFinished'),
 @('mark-after-cancelled-guard','if (!IsCurrentWorld() || creation != m_CurrentCreation || creation.m_bFinished || !m_bNativeBirthBusy || creation.m_bNativeCallStarted) return false;',''),
 @('constructor-premature-close','if (creation.m_bNativeCallStarted && !creation.m_bFactoryObserved) return false;',''),
 @('lose-external-native-return','if (RetainQuarantinedExternalReturn(creation, entity)) return;',''),
 @('lose-group-native-return','if (RetainQuarantinedGroupReturn(birth, entity)) return;',''),
 @('lose-retained-receipt','m_QuarantinedCreation = creation;',''),
 @('full-observe-post-virtual-fence','if (!IsExternalObservationCurrent(creation, guard, reservation, ticket, observedBody, entity)) return;',''),
 @('full-observe-guard-pointer','creation.m_Guard == guard','true')
)){
 if(!$code.Contains($mutation[1])){throw "Missing actual mutation target $($mutation[0])"}
 $name='Unsafe'+[guid]::NewGuid().ToString('N')
 $mutated=$code.Replace($mutation[1],$mutation[2]).Replace('public class N {',"namespace $name {public class N {")+'}'
 Add-Type $mutated
 $rejected=$false;try{$null=([type]("$name.Cases")).GetMethod('Execute').Invoke($null,@())}catch{$rejected=$true}
 if(!$rejected){throw "Unsafe creation lifecycle survived $($mutation[0])"};$unsafe++
}
